package com.bank.parity;

import java.util.*;
import java.util.logging.*;

public class PartitionDemo {
    private static final Logger log = Logger.getLogger("Parity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> ids = List.of(101, 102, 103, 104, 105);
        ParityService service = new ParityService();

        Map<Boolean, List<Integer>> split = service.splitParity(ids);
        log.info(() -> "even (true) : " + split.get(true));
        log.info(() -> "odd  (false): " + split.get(false));
    }
}

// ─── Would be in service/ParityService.java ───
class ParityService {
    Map<Boolean, List<Integer>> splitParity(List<Integer> ids) {
        return ids.stream()
            .collect(java.util.stream.Collectors.partitioningBy(n -> n % 2 == 0)); // true=even
    }
}
